import { createSelector } from "@reduxjs/toolkit";
const EMPTY_CONTEXT_ENTRIES = [];
const selectInstanceContextEntries = (conversationId) => createSelector(
  (state) => state.instanceContext.byConversationId[conversationId],
  (context) => {
    if (!context) return EMPTY_CONTEXT_ENTRIES;
    const values = Object.values(context);
    return values.length === 0 ? EMPTY_CONTEXT_ENTRIES : values;
  }
);
const selectInstanceContextEntry = (conversationId, key) => (state) => state.instanceContext.byConversationId[conversationId]?.[key];
const selectSlotMatchedContext = (conversationId) => createSelector(
  (state) => state.instanceContext.byConversationId[conversationId],
  (context) => {
    if (!context) return EMPTY_CONTEXT_ENTRIES;
    const filtered = Object.values(context).filter((e) => e.slotMatched);
    return filtered.length === 0 ? EMPTY_CONTEXT_ENTRIES : filtered;
  }
);
const selectAdHocContext = (conversationId) => createSelector(
  (state) => state.instanceContext.byConversationId[conversationId],
  (context) => {
    if (!context) return EMPTY_CONTEXT_ENTRIES;
    const filtered = Object.values(context).filter((e) => !e.slotMatched);
    return filtered.length === 0 ? EMPTY_CONTEXT_ENTRIES : filtered;
  }
);
const EMPTY_SURFACE_KEYS = [];
const selectSurfaceContextKeys = (conversationId) => (state) => state.instanceContext.surfaceKeysByConversationId[conversationId] ?? EMPTY_SURFACE_KEYS;
export {
  selectAdHocContext,
  selectInstanceContextEntries,
  selectInstanceContextEntry,
  selectSlotMatchedContext,
  selectSurfaceContextKeys
};
